REVOKE INSERT,UPDATE,DELETE ON public.sales,public.sale_items FROM authenticated;
CREATE FUNCTION public.stock_edit_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') AND NEW.stock<>OLD.stock THEN RAISE EXCEPTION 'Altere o saldo com uma movimentação'; END IF; RETURN NEW; END $$; CREATE TRIGGER stock_edit_guard BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.stock_edit_guard();
CREATE FUNCTION public.transfer_lot(lot_id uuid,destination uuid,qty numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.lots; BEGIN IF NOT public.erp_allowed('inventory','update') THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO l FROM public.lots WHERE id=lot_id AND company_id=public.current_company() FOR UPDATE; IF NOT FOUND OR qty<=0 OR qty>l.quantity OR destination=l.warehouse_id THEN RAISE EXCEPTION 'Transferência inválida'; END IF; IF NOT EXISTS(SELECT 1 FROM public.warehouses WHERE id=destination AND company_id=l.company_id) THEN RAISE EXCEPTION 'Depósito inválido'; END IF; UPDATE public.lots SET quantity=quantity-qty WHERE id=l.id; INSERT INTO public.lots(company_id,product_id,warehouse_id,code,quantity,expires_at) VALUES(l.company_id,l.product_id,destination,l.code,qty,l.expires_at) ON CONFLICT(company_id,product_id,warehouse_id,code) DO UPDATE SET quantity=lots.quantity+excluded.quantity; END $$;
REVOKE ALL ON FUNCTION public.transfer_lot(uuid,uuid,numeric) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.transfer_lot(uuid,uuid,numeric) TO authenticated;
CREATE FUNCTION public.lot_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE total numeric;available numeric; BEGIN PERFORM id FROM public.products WHERE id=NEW.product_id FOR UPDATE; SELECT stock INTO available FROM public.products WHERE id=NEW.product_id; SELECT COALESCE(sum(quantity),0) INTO total FROM public.lots WHERE product_id=NEW.product_id AND id<>NEW.id; IF total+NEW.quantity>available THEN RAISE EXCEPTION 'Quantidade dos lotes excede o saldo'; END IF; RETURN NEW; END $$; CREATE TRIGGER lot_guard BEFORE INSERT OR UPDATE ON public.lots FOR EACH ROW EXECUTE FUNCTION public.lot_guard();